   for(const [commodityId,p] of Object.entries(r.prices??{})){const bids=p.orders??[],asks=p.offers??[],depth=bids.reduce((n,b)=>n+b.remainingQuantity,0)-asks.reduce((n,a)=>n+a.remainingQuantity,0),key=r.portId+'|'+commodityId,old=observations.get(key),continuing=old&&old.shortage&&r.tick-old.lastTick<this.rules.maximum_report_age_seconds;
    const shortage=depth>=this.rules.minimum_shortage_units;observations.set(key,{portId:r.portId,commodityId,shortage,depth,firstTick:shortage&&continuing?old.firstTick:r.tick,lastTick:r.tick,samples:shortage&&continuing?Math.min(100,old.samples+1):shortage?1:0,evidence:{source:r.source,originPortId:r.originPortId,viaShipId:shipId,visitId,observationTick:r.tick,receivedAt:now,marketRevision:r.marketRevision??0},bids:copy(bids.map(b=>({priceUnits:b.priceUnits??toMicrogold(b.offeredPrice??0),remainingQuantity:b.remainingQuantity}))),bidUnits:bids.reduce((n,b)=>Math.max(n,b.priceUnits??toMicrogold(b.offeredPrice??0)),0)});
   }
